func _show_line_payout_popup(payout_cents: int) -> void:
	if _line_payout_label == null:
		return
	if _line_payout_tween != null and is_instance_valid(_line_payout_tween):
		_line_payout_tween.kill()
	_line_payout_label.text = "+%d" % payout_cents
	_line_payout_label.visible = true
	_line_payout_label.modulate = Color(1.0, 1.0, 1.0, 1.0)
	_line_payout_tween = create_tween()
	_line_payout_tween.tween_interval(LINE_PAYOUT_FADE_SEC * 0.65)
	_line_payout_tween.tween_property(_line_payout_label, "modulate:a", 0.0, LINE_PAYOUT_FADE_SEC * 0.35)
	_line_payout_tween.finished.connect(func() -> void:
		if is_instance_valid(_line_payout_label):
			_line_payout_label.visible = false
			_line_payout_label.modulate = Color(1.0, 1.0, 1.0, 1.0)
	)


func _hide_line_payout_popup(immediate: bool = false) -> void:
	if _line_payout_label == null:
		return
	if _line_payout_tween != null and is_instance_valid(_line_payout_tween):
		_line_payout_tween.kill()
		_line_payout_tween = null
	if immediate:
		_line_payout_label.visible = false
		_line_payout_label.text = ""
		_line_payout_label.modulate = Color(1.0, 1.0, 1.0, 1.0)

